bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK_VERIFY_BOT_DOWN; exit 61; }
test "$(docker ps --format '{{.Names}}' | grep -Ec '^gace-createvdobot-videobot-poll-1$')" -eq 1 || { echo STK_VERIFY_POLL_COUNT_INVALID; exit 62; }
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';import{readFileSync}from'node:fs';
const e=process.env;const productId='sp_76f23430d1c29ca355960a95';
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1});
try{
const q=await pool.query("SELECT p.product_id,p.price_stars,p.status AS product_status,t.telegram_message_id,t.status AS post_status,t.chat_id,t.message_thread_id,t.display_text FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",[productId]);
if(q.rowCount!==1)throw Error('STK_VERIFY_PRODUCT_RECEIPT_NOT_UNIQUE');
const p=q.rows[0];
if(p.product_status!=='published'||p.post_status!=='sent'||Number(p.price_stars)!==50||Number(p.telegram_message_id)<=4664||Number(p.chat_id)!==-1002373696859||Number(p.message_thread_id)!==4640||typeof p.display_text!=='string'||!p.display_text.includes('50 Stars'))throw Error('STK_VERIFY_TOPIC_RECEIPT_INVALID');
const source=readFileSync('./src/stickers/topicPublication.mjs','utf8');
const bot=readFileSync('./src/telegram/botApi.mjs','utf8');
const sales=readFileSync('./src/telegram/stickerSales.mjs','utf8');
if(!source.includes("telegramApi('sendPhoto'")||!bot.includes('there is no text in the message to edit')||!sales.includes('hentaigay'))throw Error('STK_VERIFY_SOURCE_INCOMPLETE');
const pin=JSON.parse(readFileSync('/var/lib/videobot/sticker-entry/group2373696859_thread4640.json','utf8'));
if(pin.status!=='pinned_ack'||Number(pin.thread_id)!==4640||Number(pin.message_id)===Number(p.telegram_message_id))throw Error('STK_VERIFY_PIN_CHANGED');
console.log('STK_VISIBLE_PREVIEW_POST_RECEIPT=PASS');
console.log('STK_SAME_50_STARS_PRODUCT_AND_TOPIC=PASS');
console.log('STK_PIN_PRESERVED=PASS');
console.log('STK_DM_MENU_FALLBACK_SOURCE=PASS');
console.log('STK_PUBLIC_SHOP_URL_CONFIGURED='+Boolean(e.VIDEOBOT_SHOP_PUBLIC_URL));
}finally{await pool.end();}
NODE
echo STK_INDEPENDENT_RUNTIME_READBACK=PASS
